public static class ProviderResponseBody
{
    public const int MaximumBytes = 256 * 1024;

    public static async Task<string> ReadAsync(HttpContent content, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(content);
        cancellationToken.ThrowIfCancellationRequested();
        if (content.Headers.ContentLength > MaximumBytes)
        {
            throw new InvalidDataException("The provider response exceeds the byte limit.");
        }

        using var source = await content.ReadAsStreamAsync(cancellationToken).ConfigureAwait(false);
        using var body = new MemoryStream();
        var buffer = new byte[8192];
        while (true)
        {
            var count = await source.ReadAsync(buffer.AsMemory(0, Math.Min(buffer.Length, MaximumBytes + 1 - checked((int)body.Length))), cancellationToken).ConfigureAwait(false);
            if (count == 0)
            {
                return Encoding.UTF8.GetString(body.GetBuffer(), 0, checked((int)body.Length));
            }
            if (body.Length + count > MaximumBytes)
            {
                throw new InvalidDataException("The provider response exceeds the byte limit.");
            }
            body.Write(buffer, 0, count);
        }
    }
}

static string RemoveWords(string s, Regex rx, bool requireBoundaries) => rx.Replace(s, m =>
{
    bool hasPre = m.Groups["pre"].Success;
    string post = m.Groups["post"].Success ? m.Groups["post"].Value.Trim() : "";
    bool sentenceStart = !hasPre && IsSentenceStart(s, m.Index);
    bool boundaryBefore = hasPre || PreviousChar(s, m.Index) == Pause;
    var rest = s.AsSpan(m.Index + m.Length).TrimStart(' ');
    bool boundaryAfter = post.Length > 0 || rest.IsEmpty || rest[0] == Pause;

    if (requireBoundaries && !((boundaryBefore || sentenceStart) && boundaryAfter))
        return m.Value;

    string endPunct = post.Replace(",", "");
    if (endPunct.Length > 0) return sentenceStart ? " " : endPunct + " ";
    return sentenceStart ? " " + Cap : " ";
});

