export function ensureSelectOption(sel, value, label){
  const v = String(value ?? '');
  if (!sel || v === '' || [...sel.options].some(o => o.value === v)) return;
  const o = document.createElement('option');
  o.value = v;
  o.textContent = label || v;
  sel.appendChild(o);
}

