export function interpLinear(plan: MorphPlan, t: number, out: Float64Array[]): void {
  for (let k = 0; k < plan.items.length; k++) {
    const it = plan.items[k];
    const o = out[k];
    const n = plan.n;
    for (let i = 0; i < n; i++) {
      o[2 * i] = it.a[2 * i] + (it.bO[2 * i] - it.a[2 * i]) * t;
      o[2 * i + 1] = it.a[2 * i + 1] + (it.bO[2 * i + 1] - it.a[2 * i + 1]) * t;
    }
  }
}

public static int tierColor(String tier) {
    boolean high = tier.contains("HT");
    int n = 5;
    for (int i = tier.length() - 1; i >= 0; i--) {
        if (Character.isDigit(tier.charAt(i))) {
            n = tier.charAt(i) - '0';
            break;
        }
    }
    int[] highCols = {0xFFC94D, 0xFF9F43, 0xFF6B6B, 0xC77DFF, 0x9AA5B1};
    int[] lowCols = {0xE8C86A, 0xE08A3A, 0xD05A5A, 0xA060D8, 0x7C8794};
    int idx = Math.max(1, Math.min(5, n)) - 1;
    return high ? highCols[idx] : lowCols[idx];
}

public class JsonTypeHandler<T> : SqlMapper.TypeHandler<T> where T : new()
{
    private static readonly JsonSerializerOptions Options = new(JsonSerializerDefaults.Web);

    public override void SetValue(IDbDataParameter parameter, T? value)
    {
        parameter.DbType = DbType.String;
        parameter.Value = JsonSerializer.Serialize(value, Options);
    }

    public override T Parse(object? value) =>
        value is string s && !string.IsNullOrWhiteSpace(s)
            ? JsonSerializer.Deserialize<T>(s, Options) ?? new T()
            : new T();
}

