  let d = "";
  for (const { pts, closed } of paths) {
    d += `M${fmtCanon(pts[0])} ${fmtCanon(pts[1])}`;
    for (let i = 2; i < pts.length; i += 6) {
      d += `C${fmtCanon(pts[i])} ${fmtCanon(pts[i + 1])} ${fmtCanon(pts[i + 2])} ${fmtCanon(
        pts[i + 3],
      )} ${fmtCanon(pts[i + 4])} ${fmtCanon(pts[i + 5])}`;
    }
    if (closed) d += "Z";
  }
  return d;
}

