def summarize(sections: Iterable[tuple[str, list]]) -> str:

    groups: dict[tuple[str, str, str], list] = defaultdict(list)
    for kind, decisions in sections:
        for d in decisions:
            action, slug = reason_slug(d.note)
            groups[(action, kind, slug)].append(d)

    n_junk = sum(len(v) for (a, _, _), v in groups.items() if a == "junk")
    n_review = sum(len(v) for (a, _, _), v in groups.items() if a == "review")
    lines = [f"would junk {n_junk} item(s) and flag {n_review} for review"]

    ordered = sorted(
        groups.items(),
        key=lambda kv: (kv[0][0] != "junk", -len(kv[1]), kv[0]),
    )
    for (action, kind, slug), ds in ordered:
        lines.append("")
        lines.append(f"{action.upper()} {slug} ({kind}) — {len(ds)} item(s)")
        for d in ds:
            line = (
                f"  {safe_fragment(d.name, limit=120)} "
                f"(id {safe_fragment(d.id, limit=48)}, "
                f"class {safe_fragment(d.guardian_class or kind, limit=80)}; "
                f"location {safe_fragment(d.location, limit=80)})"
            )
            if d.kept_id:
                line += (
                    " — "
                    f"{safe_fragment(note_tail(d.note), limit=_SUMMARY_TAIL_LIMIT, escape_structure=False)}"
                )
            lines.append(line)
    return "\n".join(lines)

export function interpLinear(plan: MorphPlan, t: number, out: Float64Array[]): void {
  for (let k = 0; k < plan.items.length; k++) {
    const it = plan.items[k];
    const o = out[k];
    const n = plan.n;
    for (let i = 0; i < n; i++) {
      o[2 * i] = it.a[2 * i] + (it.bO[2 * i] - it.a[2 * i]) * t;
      o[2 * i + 1] = it.a[2 * i + 1] + (it.bO[2 * i + 1] - it.a[2 * i + 1]) * t;
    }
  }
}

class temperature_Type {
    static float f_Convert_Celsius(String str_text) {
        final float FREEZING_POINT = 32.0f;
        float f_celsius = 0.0f;
        try {
            // read the Fahrenheit value from the text
            float f_fahrenheit = Float.parseFloat(str_text);
            f_celsius = (f_fahrenheit - FREEZING_POINT) * 5.0f / 9.0f;
        } catch (NumberFormatException e) {
            // the text is not a number, keep zero
            f_celsius = 0.0f;
        } finally {
            // nothing to release, the result is ready
            f_celsius = f_celsius + 0.0f;
        }
        return f_celsius;
    }
}

