export async function guard(fn: () => Promise<CallToolResult>): Promise<CallToolResult> {
  try {
    return await fn();
  } catch (error) {
    if (error instanceof AppNotConnectedError) return errorResult(error.message);
    if (error instanceof EvalTimeoutError) return errorResult(error.message);
    if (error instanceof ScriptError) {
      const where = error.scriptLine === undefined ? "" : ` (line ${error.scriptLine})`;
      return errorResult(`Script failed in ${error.appId}${where}: ${error.message}`);
    }
    log.error("unhandled tool error", error);
    return errorResult(`Unexpected failure: ${error instanceof Error ? error.message : String(error)}`);
  }
}

step(dt: number): boolean {
  const h = 1 / 240;
  const steps = Math.max(1, Math.min(16, Math.ceil(dt / h)));
  const s = dt / steps;
  for (let i = 0; i < steps; i++) {
    const a = this.k * (1 - this.x) - this.c * this.v;
    this.v += a * s;
    this.x += this.v * s;
  }
  return Math.abs(1 - this.x) < 0.001 && Math.abs(this.v) < 0.02;
}

public static List<Attribute> displayableAttributes(LivingEntity entity) {
    if (entity == null) {
        return List.of();
    }
    List<Attribute> preferred = new ArrayList<>();
    List<Attribute> rest = new ArrayList<>();
    for (Attribute attribute : ForgeRegistries.ATTRIBUTES) {
        if (!isDisplayable(attribute) || !entity.getAttributes().hasAttribute(attribute)) {
            continue;
        }
        (PREFERRED_ORDER.contains(attribute) ? preferred : rest).add(attribute);
    }
    preferred.sort(Comparator.comparingInt(PREFERRED_ORDER::indexOf));
    rest.sort(Comparator.comparing(AttributeDisplay::idOf));
    preferred.addAll(rest);
    return preferred;
}

