public static List<Attribute> displayableAttributes(LivingEntity entity) {
    if (entity == null) {
        return List.of();
    }
    List<Attribute> preferred = new ArrayList<>();
    List<Attribute> rest = new ArrayList<>();
    for (Attribute attribute : ForgeRegistries.ATTRIBUTES) {
        if (!isDisplayable(attribute) || !entity.getAttributes().hasAttribute(attribute)) {
            continue;
        }
        (PREFERRED_ORDER.contains(attribute) ? preferred : rest).add(attribute);
    }
    preferred.sort(Comparator.comparingInt(PREFERRED_ORDER::indexOf));
    rest.sort(Comparator.comparing(AttributeDisplay::idOf));
    preferred.addAll(rest);
    return preferred;
}

public static void show(DrawContext context, int x1, int y1, int x2, int y2, float scale, float yaw, LivingEntity entity) {
    if (entity == null || context == null || x2 <= x1 || y2 <= y1) {
        return;
    }
    drawing = true;
    try {
        var dispatcher = MinecraftClient.getInstance().getEntityRenderDispatcher();
        EntityRenderer<? super LivingEntity, ?> renderer = dispatcher.getRenderer(entity);
        EntityRenderState state = renderer.getAndUpdateRenderState(entity, 1.0F);
        state.light = 15728880;
        state.outlineColor = 0;
        if (state instanceof LivingEntityRenderState living && living.baseScale > 0f) {
            living.bodyYaw = yaw;
            living.relativeHeadYaw = 0f;
            living.pitch = 0f;
            living.width = living.width / living.baseScale;
            living.height = living.height / living.baseScale;
            living.baseScale = 1.0F;
        }
        Vector3f offset = new Vector3f(0f, state.height / 2f + 0.0625f, 0f);
        Quaternionf rot = new Quaternionf().rotateZ((float) Math.PI);
        // Entity previews are placed in screen pixels and ignore the pose matrix, so a scaled menu
        // has to map its bounds and size through the current matrix itself.
        var m = context.getMatrices();
        org.joml.Vector2f p1 = m.transformPosition(new org.joml.Vector2f(x1, y1));
        org.joml.Vector2f p2 = m.transformPosition(new org.joml.Vector2f(x2, y2));
        float k = m.m00();
        context.addEntity(state, scale * k, offset, rot, new Quaternionf(),
                Math.round(p1.x), Math.round(p1.y), Math.round(p2.x), Math.round(p2.y));
    } catch (Throwable t) {
        t.printStackTrace();
    } finally {
        drawing = false;
    }
}

public static async Task EnsureModelAsync(AppSettings s, IProgress<long>? progressMb, CancellationToken ct)
{
    string path = ModelPath(s.ModelType, s.ModelQuantization);
    if (File.Exists(path)) return;

    Directory.CreateDirectory(AppPaths.Models);
    string partial = path + ".part";
    Log.Write($"Downloading model {s.ModelType} {s.ModelQuantization}");
    await using (var source = await WhisperGgmlDownloader.Default.GetGgmlModelAsync(s.ModelType, s.ModelQuantization, ct))
    await using (var target = File.Create(partial))
    {
        var buffer = new byte[1 << 20];
        long total = 0, lastMb = -1;
        int read;
        while ((read = await source.ReadAsync(buffer, ct)) > 0)
        {
            await target.WriteAsync(buffer.AsMemory(0, read), ct);
            total += read;
            long mb = total >> 20;
            if (mb != lastMb) progressMb?.Report(lastMb = mb);
        }
    }
    File.Move(partial, path, overwrite: true);
    Log.Write("Model download complete");
}

