public static boolean hasLoadedDuplicate(MinecraftServer server, FurkinArchiveEntry entry) {
    if (server == null || entry == null || entry.getCompanionId() == null) {
        return false;
    }
    UUID companionId = entry.getCompanionId();
    UUID canonicalUuid = entry.getEntityUuid();
    Set<UUID> registered = LOADED_ENTITIES.get(companionId);
    if (registered == null || registered.isEmpty()) {
        LOADED_ENTITIES.remove(companionId);
        return false;
    }

    boolean found = false;
    Iterator<UUID> iterator = registered.iterator();
    while (iterator.hasNext()) {
        UUID entityUuid = iterator.next();
        LivingEntity loaded = findLoaded(server, entityUuid);
        if (loaded == null) {
            iterator.remove();
            continue;
        }
        FurkinData data = loaded.getCapability(FurkinCapability.FURKIN_DATA).orElse(null);
        if (data == null || !companionId.equals(data.getCompanionId())) {
            iterator.remove();
            continue;
        }
        if (canonicalUuid == null || !canonicalUuid.equals(entityUuid)) {
            found = true;
        }
    }
    if (registered.isEmpty()) {
        LOADED_ENTITIES.remove(companionId);
    }
    return found;
}

static string RemoveWords(string s, Regex rx, bool requireBoundaries) => rx.Replace(s, m =>
{
    bool hasPre = m.Groups["pre"].Success;
    string post = m.Groups["post"].Success ? m.Groups["post"].Value.Trim() : "";
    bool sentenceStart = !hasPre && IsSentenceStart(s, m.Index);
    bool boundaryBefore = hasPre || PreviousChar(s, m.Index) == Pause;
    var rest = s.AsSpan(m.Index + m.Length).TrimStart(' ');
    bool boundaryAfter = post.Length > 0 || rest.IsEmpty || rest[0] == Pause;

    if (requireBoundaries && !((boundaryBefore || sentenceStart) && boundaryAfter))
        return m.Value;

    string endPunct = post.Replace(",", "");
    if (endPunct.Length > 0) return sentenceStart ? " " : endPunct + " ";
    return sentenceStart ? " " + Cap : " ";
});

