export async function guard(fn: () => Promise<CallToolResult>): Promise<CallToolResult> {
  try {
    return await fn();
  } catch (error) {
    if (error instanceof AppNotConnectedError) return errorResult(error.message);
    if (error instanceof EvalTimeoutError) return errorResult(error.message);
    if (error instanceof ScriptError) {
      const where = error.scriptLine === undefined ? "" : ` (line ${error.scriptLine})`;
      return errorResult(`Script failed in ${error.appId}${where}: ${error.message}`);
    }
    log.error("unhandled tool error", error);
    return errorResult(`Unexpected failure: ${error instanceof Error ? error.message : String(error)}`);
  }
}

def strip_trailing_tool_clauses(notes: object) -> str:

    remaining = str(notes).strip()
    while remaining:
        markers = tuple(_MARKER_RE.finditer(remaining))
        if not markers:
            break
        start = markers[-1].start(1)
        suffix = remaining[start:]
        if not any(pattern.fullmatch(suffix) for pattern in _GENERATED_CLAUSE_RES):
            break
        remaining = remaining[:start].rstrip()
    return remaining

export function serialize(
  subs: readonly Float64Array[],
  closed?: readonly boolean[],
): string {
  let d = "";
  for (let k = 0; k < subs.length; k++) {
    const o = subs[k];
    const n = o.length / 2;
    d += `M${fmt(o[0])} ${fmt(o[1])}`;
    for (let i = 1; i < n; i++) d += `L${fmt(o[2 * i])} ${fmt(o[2 * i + 1])}`;
    if (closed?.[k]) d += "Z";
  }
  return d;
}

