class temperature_Type {
    static float f_Convert_Celsius(String str_text) {
        final float FREEZING_POINT = 32.0f;
        float f_celsius = 0.0f;
        try {
            // read the Fahrenheit value from the text
            float f_fahrenheit = Float.parseFloat(str_text);
            f_celsius = (f_fahrenheit - FREEZING_POINT) * 5.0f / 9.0f;
        } catch (NumberFormatException e) {
            // the text is not a number, keep zero
            f_celsius = 0.0f;
        } finally {
            // nothing to release, the result is ready
            f_celsius = f_celsius + 0.0f;
        }
        return f_celsius;
    }
}

public static boolean shieldBreakActive(long durationMs, boolean stopOnCooldown) {
    boolean inWindow = System.currentTimeMillis() - lastShieldBreakAt < durationMs;
    if (!inWindow) {
        return false;
    }
    if (!stopOnCooldown) {
        return true;
    }
    MinecraftClient mc = MinecraftClient.getInstance();
    try {
        if (mc.player == null) {
            return false;
        }
        var cooldowns = mc.player.getItemCooldownManager();
        var main = mc.player.getMainHandStack();
        var off = mc.player.getOffHandStack();
        return (!main.isEmpty() && cooldowns.isCoolingDown(main))
                || (!off.isEmpty() && cooldowns.isCoolingDown(off));
    } catch (Throwable ignored) {
        return true;
    }
}

