export async function guard(fn: () => Promise<CallToolResult>): Promise<CallToolResult> {
  try {
    return await fn();
  } catch (error) {
    if (error instanceof AppNotConnectedError) return errorResult(error.message);
    if (error instanceof EvalTimeoutError) return errorResult(error.message);
    if (error instanceof ScriptError) {
      const where = error.scriptLine === undefined ? "" : ` (line ${error.scriptLine})`;
      return errorResult(`Script failed in ${error.appId}${where}: ${error.message}`);
    }
    log.error("unhandled tool error", error);
    return errorResult(`Unexpected failure: ${error instanceof Error ? error.message : String(error)}`);
  }
}

def discover_export(kind: str, input_dir: str | Path) -> Path:

    directory = Path(input_dir)
    pattern = EXPORT_PATTERNS[kind]
    try:
        entries = directory.iterdir()
        candidates = sorted(
            (
                entry
                for entry in entries
                if pattern.fullmatch(entry.name) and entry.is_file()
            ),
            key=lambda entry: entry.name,
        )
    except FileNotFoundError:
        candidates = []
    except OSError as e:
        raise ExportDiscoveryError(
            f"could not search for {kind} exports in {directory}: {e}"
        ) from e

    if not candidates:
        raise MissingExportError(kind, directory)
    if len(candidates) > 1:
        raise AmbiguousExportError(
            kind,
            directory,
            tuple(candidate.name for candidate in candidates),
        )
    return candidates[0]

public sealed class WorldObservationClient(HttpClient httpClient)
{
    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNameCaseInsensitive = true,
    };

    public async Task<WorldObservation> ReconnectAsync(Uri worldBaseUri, long afterEventId, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(worldBaseUri);
        ArgumentOutOfRangeException.ThrowIfNegative(afterEventId);

        var handshakeUri = new Uri(worldBaseUri, "/api/v1/handshake");
        var reconnectUri = new Uri(worldBaseUri, $"/api/v1/reconnect?afterEventId={afterEventId}");
        var handshakeTask = httpClient.GetFromJsonAsync<WorldHandshake>(handshakeUri, JsonOptions, cancellationToken);
        var reconnectTask = httpClient.GetFromJsonAsync<WorldReconnectBaseline>(reconnectUri, JsonOptions, cancellationToken);
        await Task.WhenAll(handshakeTask, reconnectTask);

        var handshake = await handshakeTask ?? throw new InvalidDataException("Server returned an empty handshake.");
        var baseline = await reconnectTask ?? throw new InvalidDataException("Server returned an empty reconnect baseline.");
        return new WorldObservation(handshake, baseline);
    }
}

