{
    var asm = typeof(MigrationRunner).Assembly;
    var names = asm.GetManifestResourceNames()
        .Where(n => n.StartsWith(ScriptPrefix) && n.EndsWith(".sql"))
        .OrderBy(n => n, StringComparer.Ordinal);

    foreach (var name in names)
