def row_perk_hashes(row: pd.Series, perk_map: dict[str, frozenset[int]]) -> frozenset[int]:

    hashes: set[int] = set()
    for col in row.index:
        if not col.startswith("Perks "):
            continue
        name = str(row[col]).strip().removesuffix("*").strip().casefold()
        if name:
            hashes |= perk_map.get(name, frozenset())
    return frozenset(hashes)

def extract_repo_sections(content: str) -> tuple[list[dict[str, str]], list[str]]:

    repo_info = []
    raw_sections = []

    details_pattern = r'<!-- repo:(.*?) -->\s*<details>[\s\S]*?</details>'
    for match in re.finditer(details_pattern, content):
        repo_name = match.group(1).strip()
        section_text = match.group(0)
        raw_sections.append(section_text)
        repo_info.append({
            "name": repo_name,
            "url": "",
            "text": section_text,
        })

    if repo_info:
        return repo_info, raw_sections

    section_pattern = r'## 📂 \[(.*?)\]\((.*?)\)[\s\S]*?(?=## 📂|<!-- repo:|\Z)'
    for match in re.finditer(section_pattern, content):
        section_text = match.group(0)
        raw_sections.append(section_text)
        repo_info.append({
            "name": match.group(1),
            "url": match.group(2),
            "text": section_text,
        })

    return repo_info, raw_sections

public static async Task EnsureModelAsync(AppSettings s, IProgress<long>? progressMb, CancellationToken ct)
{
    string path = ModelPath(s.ModelType, s.ModelQuantization);
    if (File.Exists(path)) return;

    Directory.CreateDirectory(AppPaths.Models);
    string partial = path + ".part";
    Log.Write($"Downloading model {s.ModelType} {s.ModelQuantization}");
    await using (var source = await WhisperGgmlDownloader.Default.GetGgmlModelAsync(s.ModelType, s.ModelQuantization, ct))
    await using (var target = File.Create(partial))
    {
        var buffer = new byte[1 << 20];
        long total = 0, lastMb = -1;
        int read;
        while ((read = await source.ReadAsync(buffer, ct)) > 0)
        {
            await target.WriteAsync(buffer.AsMemory(0, read), ct);
            total += read;
            long mb = total >> 20;
            if (mb != lastMb) progressMb?.Report(lastMb = mb);
        }
    }
    File.Move(partial, path, overwrite: true);
    Log.Write("Model download complete");
}

