function useConversacion() {
  const [mensajes, setMensajes] = useState<Mensaje[]>([])
  const [respondiendo, setRespondiendo] = useState(false)
  const espera = useRef<ReturnType<typeof setTimeout> | null>(null)
  const proximo = useRef(1)

  const enviar = (texto: string) => {
    setMensajes((lista) => [...lista, { id: proximo.current++, from: "user", texto }])
    setRespondiendo(true)
    espera.current = setTimeout(() => {
      const respuesta = RESPUESTAS[texto] ?? "Eso no lo tengo a mano todavía."
      setMensajes((lista) => [...lista, { id: proximo.current++, from: "assistant", texto: respuesta }])
      setRespondiendo(false)
    }, 1400)
  }
  const cortar = () => {
    if (espera.current) clearTimeout(espera.current)
    setRespondiendo(false)
  }
  const nueva = () => {
    cortar()
    setMensajes([])
  }
  return { mensajes, respondiendo, enviar, cortar, nueva }
}

private static void tickModuleToggleKeys(MinecraftClient client) {
    if (MODULES == null || client.currentScreen != null || client.getWindow() == null) {
        return;
    }
    long handle = client.getWindow().getHandle();
    for (dev.aero.client.module.Module module : MODULES.all) {
        int key = module.style().toggleKey;
        if (key < 0) {
            continue;
        }
        boolean down;
        try {
            down = GLFW.glfwGetKey(handle, key) == GLFW.GLFW_PRESS;
        } catch (Throwable ignored) {
            continue;
        }
        boolean was = Boolean.TRUE.equals(moduleKeyWasDown.get(module.name));
        if (down && !was) {
            if ("Screenshot".equals(module.name)) {
                if (module.enabled()) {
                    Screenshots.capture(client);
                }
            } else if (!"Emotes".equals(module.name)) {
                module.toggle();
                CONFIG.save();
                dev.aero.client.ui.Notifications.toggled(module);
            }
        }
        moduleKeyWasDown.put(module.name, down);
    }
}

