def extract_repo_sections(content: str) -> tuple[list[dict[str, str]], list[str]]:

    repo_info = []
    raw_sections = []

    details_pattern = r'<!-- repo:(.*?) -->\s*<details>[\s\S]*?</details>'
    for match in re.finditer(details_pattern, content):
        repo_name = match.group(1).strip()
        section_text = match.group(0)
        raw_sections.append(section_text)
        repo_info.append({
            "name": repo_name,
            "url": "",
            "text": section_text,
        })

    if repo_info:
        return repo_info, raw_sections

    section_pattern = r'## 📂 \[(.*?)\]\((.*?)\)[\s\S]*?(?=## 📂|<!-- repo:|\Z)'
    for match in re.finditer(section_pattern, content):
        section_text = match.group(0)
        raw_sections.append(section_text)
        repo_info.append({
            "name": match.group(1),
            "url": match.group(2),
            "text": section_text,
        })

    return repo_info, raw_sections

public static int tierColor(String tier) {
    boolean high = tier.contains("HT");
    int n = 5;
    for (int i = tier.length() - 1; i >= 0; i--) {
        if (Character.isDigit(tier.charAt(i))) {
            n = tier.charAt(i) - '0';
            break;
        }
    }
    int[] highCols = {0xFFC94D, 0xFF9F43, 0xFF6B6B, 0xC77DFF, 0x9AA5B1};
    int[] lowCols = {0xE8C86A, 0xE08A3A, 0xD05A5A, 0xA060D8, 0x7C8794};
    int idx = Math.max(1, Math.min(5, n)) - 1;
    return high ? highCols[idx] : lowCols[idx];
}

