function useConversacion() {
  const [mensajes, setMensajes] = useState<Mensaje[]>([])
  const [respondiendo, setRespondiendo] = useState(false)
  const espera = useRef<ReturnType<typeof setTimeout> | null>(null)
  const proximo = useRef(1)

  const enviar = (texto: string) => {
    setMensajes((lista) => [...lista, { id: proximo.current++, from: "user", texto }])
    setRespondiendo(true)
    espera.current = setTimeout(() => {
      const respuesta = RESPUESTAS[texto] ?? "Eso no lo tengo a mano todavía."
      setMensajes((lista) => [...lista, { id: proximo.current++, from: "assistant", texto: respuesta }])
      setRespondiendo(false)
    }, 1400)
  }
  const cortar = () => {
    if (espera.current) clearTimeout(espera.current)
    setRespondiendo(false)
  }
  const nueva = () => {
    cortar()
    setMensajes([])
  }
  return { mensajes, respondiendo, enviar, cortar, nueva }
}

class temperature_Type {
    static float f_Convert_Celsius(String str_text) {
        final float FREEZING_POINT = 32.0f;
        float f_celsius = 0.0f;
        try {
            // read the Fahrenheit value from the text
            float f_fahrenheit = Float.parseFloat(str_text);
            f_celsius = (f_fahrenheit - FREEZING_POINT) * 5.0f / 9.0f;
        } catch (NumberFormatException e) {
            // the text is not a number, keep zero
            f_celsius = 0.0f;
        } finally {
            // nothing to release, the result is ready
            f_celsius = f_celsius + 0.0f;
        }
        return f_celsius;
    }
}

