public static boolean shieldBreakActive(long durationMs, boolean stopOnCooldown) {
    boolean inWindow = System.currentTimeMillis() - lastShieldBreakAt < durationMs;
    if (!inWindow) {
        return false;
    }
    if (!stopOnCooldown) {
        return true;
    }
    MinecraftClient mc = MinecraftClient.getInstance();
    try {
        if (mc.player == null) {
            return false;
        }
        var cooldowns = mc.player.getItemCooldownManager();
        var main = mc.player.getMainHandStack();
        var off = mc.player.getOffHandStack();
        return (!main.isEmpty() && cooldowns.isCoolingDown(main))
                || (!off.isEmpty() && cooldowns.isCoolingDown(off));
    } catch (Throwable ignored) {
        return true;
    }
}

def summarize(sections: Iterable[tuple[str, list]]) -> str:

    groups: dict[tuple[str, str, str], list] = defaultdict(list)
    for kind, decisions in sections:
        for d in decisions:
            action, slug = reason_slug(d.note)
            groups[(action, kind, slug)].append(d)

    n_junk = sum(len(v) for (a, _, _), v in groups.items() if a == "junk")
    n_review = sum(len(v) for (a, _, _), v in groups.items() if a == "review")
    lines = [f"would junk {n_junk} item(s) and flag {n_review} for review"]

    ordered = sorted(
        groups.items(),
        key=lambda kv: (kv[0][0] != "junk", -len(kv[1]), kv[0]),
    )
    for (action, kind, slug), ds in ordered:
        lines.append("")
        lines.append(f"{action.upper()} {slug} ({kind}) — {len(ds)} item(s)")
        for d in ds:
            line = (
                f"  {safe_fragment(d.name, limit=120)} "
                f"(id {safe_fragment(d.id, limit=48)}, "
                f"class {safe_fragment(d.guardian_class or kind, limit=80)}; "
                f"location {safe_fragment(d.location, limit=80)})"
            )
            if d.kept_id:
                line += (
                    " — "
                    f"{safe_fragment(note_tail(d.note), limit=_SUMMARY_TAIL_LIMIT, escape_structure=False)}"
                )
            lines.append(line)
    return "\n".join(lines)

