def append_rows(
    connection: Connection, table: Table, rows: Sequence[dict[str, Any]]
) -> int:

    if not rows:
        return 0
    dialect = connection.dialect.name
    pk_column = next(iter(table.primary_key.columns))
    statement: Insert
    if dialect == "postgresql":
        statement = (
            pg_insert(table)
            .values(list(rows))
            .on_conflict_do_nothing()
            .returning(pk_column)
        )
    elif dialect == "sqlite":
        statement = (
            sqlite_insert(table)
            .values(list(rows))
            .on_conflict_do_nothing()
            .returning(pk_column)
        )
    else:
        statement = insert(table).values(list(rows))
    result = connection.execute(statement)
    if result.returns_rows:
        return len(result.fetchall())
    return int(result.rowcount or 0)

public static void show(DrawContext context, int x1, int y1, int x2, int y2, float scale, float yaw, LivingEntity entity) {
    if (entity == null || context == null || x2 <= x1 || y2 <= y1) {
        return;
    }
    drawing = true;
    try {
        var dispatcher = MinecraftClient.getInstance().getEntityRenderDispatcher();
        EntityRenderer<? super LivingEntity, ?> renderer = dispatcher.getRenderer(entity);
        EntityRenderState state = renderer.getAndUpdateRenderState(entity, 1.0F);
        state.light = 15728880;
        state.outlineColor = 0;
        if (state instanceof LivingEntityRenderState living && living.baseScale > 0f) {
            living.bodyYaw = yaw;
            living.relativeHeadYaw = 0f;
            living.pitch = 0f;
            living.width = living.width / living.baseScale;
            living.height = living.height / living.baseScale;
            living.baseScale = 1.0F;
        }
        Vector3f offset = new Vector3f(0f, state.height / 2f + 0.0625f, 0f);
        Quaternionf rot = new Quaternionf().rotateZ((float) Math.PI);
        // Entity previews are placed in screen pixels and ignore the pose matrix, so a scaled menu
        // has to map its bounds and size through the current matrix itself.
        var m = context.getMatrices();
        org.joml.Vector2f p1 = m.transformPosition(new org.joml.Vector2f(x1, y1));
        org.joml.Vector2f p2 = m.transformPosition(new org.joml.Vector2f(x2, y2));
        float k = m.m00();
        context.addEntity(state, scale * k, offset, rot, new Quaternionf(),
                Math.round(p1.x), Math.round(p1.y), Math.round(p2.x), Math.round(p2.y));
    } catch (Throwable t) {
        t.printStackTrace();
    } finally {
        drawing = false;
    }
}

export function svgToIcon(markup: string): IconInput {
  if (markup.trimStart().charCodeAt(0) !== 60 /* "<" */)
    throw new Error(
      "morphicons: svgToIcon expects SVG markup — a d string or IconNode is already an IconInput",
    );
  const body = markup.replace(SVG_CONTAINER, "");
  // morphicons morphs stroke centerlines only. A stroke icon declares a stroke
  // (Lucide: stroke="currentColor") or fill="none"; a fill-drawn icon
  // (Material Symbols) declares neither → its silhouette can't read as a stroke.
  const hasStroke = /stroke\s*=\s*["'](?!\s*none\s*["'])/i.test(body);
  const fillNone = /fill\s*=\s*["']\s*none\s*["']/i.test(body);
  if (!hasStroke && !fillNone)
    throw new Error(
      "morphicons: SVG looks fill-drawn (no stroke) — only stroke-centerline icons morph",
    );
  const node: Array<readonly [string, IconNodeAttrs]> = [];
  SVG_ELEMENT.lastIndex = 0;
  let m: RegExpExecArray | null;
  // biome-ignore lint/suspicious/noAssignInExpressions: standard regex drain.
  while ((m = SVG_ELEMENT.exec(body)) !== null) {
    const tag = m[1].toLowerCase();
    if (SVG_SKIP.has(tag)) continue;
    if (!SVG_GEOMETRY.has(tag))
      throw new Error(`morphicons: unsupported SVG element <${tag}>`);
    const attrs = readSvgAttrs(m[2]);
    if ("transform" in attrs)
      throw new Error(`morphicons: <${tag}> has a transform (unsupported)`);
    node.push([tag, attrs]);
  }
  if (node.length === 0) throw new Error("morphicons: no morphable geometry in SVG");
  const vb = SVG_VIEWBOX.exec(markup);
  return vb ? fitIcon(node, vb[1]) : node;
}

