def strip_trailing_tool_clauses(notes: object) -> str:

    remaining = str(notes).strip()
    while remaining:
        markers = tuple(_MARKER_RE.finditer(remaining))
        if not markers:
            break
        start = markers[-1].start(1)
        suffix = remaining[start:]
        if not any(pattern.fullmatch(suffix) for pattern in _GENERATED_CLAUSE_RES):
            break
        remaining = remaining[:start].rstrip()
    return remaining

export function readHandshake(path: string): Handshake | null {
  try {
    const p = JSON.parse(readFileSync(path, "utf8")) as Partial<Handshake>;
    if (typeof p.port !== "number" || typeof p.pid !== "number" || typeof p.token !== "string" || typeof p.protocolVersion !== "number") return null;
    return { protocolVersion: p.protocolVersion, port: p.port, token: p.token, pid: p.pid };
  } catch {
    return null;
  }
}

