public static void onIncoming(Text message) {
    var c = AeroClient.CONFIG;
    if (c == null || !c.chatTranslate || message == null) {
        return;
    }
    String line = message.getString();
    if (line.startsWith(MARK) || line.length() > 256) {
        return;
    }
    Matcher m = CHAT.matcher(line.replaceAll("§.", "").trim());
    if (!m.matches()) {
        return;
    }
    String sender = m.group(1) != null ? m.group(1) : m.group(2);
    MinecraftClient mc = MinecraftClient.getInstance();
    if (sender == null || sender.equalsIgnoreCase(mc.getSession().getUsername())) {
        return;
    }
    String body = m.group(3).trim();
    if (body.codePoints().noneMatch(Character::isLetter)) {
        return;
    }
    translate(body, code(c.chatTranslateLang), out -> {
        if (out != null && mc.inGameHud != null) {
            mc.inGameHud.getChatHud().addMessage(Text.literal(MARK + out).formatted(Formatting.GRAY, Formatting.ITALIC));
        }
    });
}

public static boolean hasLoadedDuplicate(MinecraftServer server, FurkinArchiveEntry entry) {
    if (server == null || entry == null || entry.getCompanionId() == null) {
        return false;
    }
    UUID companionId = entry.getCompanionId();
    UUID canonicalUuid = entry.getEntityUuid();
    Set<UUID> registered = LOADED_ENTITIES.get(companionId);
    if (registered == null || registered.isEmpty()) {
        LOADED_ENTITIES.remove(companionId);
        return false;
    }

    boolean found = false;
    Iterator<UUID> iterator = registered.iterator();
    while (iterator.hasNext()) {
        UUID entityUuid = iterator.next();
        LivingEntity loaded = findLoaded(server, entityUuid);
        if (loaded == null) {
            iterator.remove();
            continue;
        }
        FurkinData data = loaded.getCapability(FurkinCapability.FURKIN_DATA).orElse(null);
        if (data == null || !companionId.equals(data.getCompanionId())) {
            iterator.remove();
            continue;
        }
        if (canonicalUuid == null || !canonicalUuid.equals(entityUuid)) {
