export function jsStringLiteral(value: string): string {
  let out = '"';
  for (const ch of value) {
    const mapped = SIMPLE_ESCAPES[ch];
    if (mapped !== undefined) {
      out += mapped;
      continue;
    }
    const code = ch.codePointAt(0)!;
    // U+2028 / U+2029 are JS line terminators; C0/C1 controls must not appear
    // raw in source. All of these are in the BMP, so a 4-digit \uXXXX escape is
    // always sufficient (and ES3-valid). Everything else passes through.
    if (code < 0x20 || (code >= 0x7f && code <= 0x9f) || code === 0x2028 || code === 0x2029) {
      out += `\\u${code.toString(16).padStart(4, "0")}`;
    } else {
      out += ch;
    }
  }
  return out + '"';
}

public static List<Attribute> displayableAttributes(LivingEntity entity) {
    if (entity == null) {
        return List.of();
    }
    List<Attribute> preferred = new ArrayList<>();
    List<Attribute> rest = new ArrayList<>();
    for (Attribute attribute : ForgeRegistries.ATTRIBUTES) {
        if (!isDisplayable(attribute) || !entity.getAttributes().hasAttribute(attribute)) {
            continue;
        }
        (PREFERRED_ORDER.contains(attribute) ? preferred : rest).add(attribute);
    }
    preferred.sort(Comparator.comparingInt(PREFERRED_ORDER::indexOf));
    rest.sort(Comparator.comparing(AttributeDisplay::idOf));
    preferred.addAll(rest);
    return preferred;
}

class temperature_Type {
    static float f_Convert_Celsius(String str_text) {
        final float FREEZING_POINT = 32.0f;
        float f_celsius = 0.0f;
        try {
            // read the Fahrenheit value from the text
            float f_fahrenheit = Float.parseFloat(str_text);
            f_celsius = (f_fahrenheit - FREEZING_POINT) * 5.0f / 9.0f;
        } catch (NumberFormatException e) {
            // the text is not a number, keep zero
            f_celsius = 0.0f;
        } finally {
            // nothing to release, the result is ready
            f_celsius = f_celsius + 0.0f;
        }
        return f_celsius;
    }
}

