def row_perk_hashes(row: pd.Series, perk_map: dict[str, frozenset[int]]) -> frozenset[int]:

    hashes: set[int] = set()
    for col in row.index:
        if not col.startswith("Perks "):
            continue
        name = str(row[col]).strip().removesuffix("*").strip().casefold()
        if name:
            hashes |= perk_map.get(name, frozenset())
    return frozenset(hashes)

export function pidAlive(pid: number, kill: (pid: number, signal: number) => void = process.kill): boolean {
  if (!Number.isInteger(pid) || pid <= 0 || pid === process.pid) return false;
  try {
    kill(pid, 0);
    return true;
  } catch (e) {
    return (e as NodeJS.ErrnoException).code === "EPERM";
  }
}

def discover_export(kind: str, input_dir: str | Path) -> Path:

    directory = Path(input_dir)
    pattern = EXPORT_PATTERNS[kind]
    try:
        entries = directory.iterdir()
        candidates = sorted(
            (
                entry
                for entry in entries
                if pattern.fullmatch(entry.name) and entry.is_file()
            ),
            key=lambda entry: entry.name,
        )
    except FileNotFoundError:
        candidates = []
    except OSError as e:
        raise ExportDiscoveryError(
            f"could not search for {kind} exports in {directory}: {e}"
        ) from e

    if not candidates:
        raise MissingExportError(kind, directory)
    if len(candidates) > 1:
        raise AmbiguousExportError(
            kind,
            directory,
            tuple(candidate.name for candidate in candidates),
        )
    return candidates[0]

step(dt: number): boolean {
  const h = 1 / 240;
  const steps = Math.max(1, Math.min(16, Math.ceil(dt / h)));
  const s = dt / steps;
  for (let i = 0; i < steps; i++) {
    const a = this.k * (1 - this.x) - this.c * this.v;
    this.v += a * s;
    this.x += this.v * s;
  }
  return Math.abs(1 - this.x) < 0.001 && Math.abs(this.v) < 0.02;
}

