function useConversacion() {
  const [mensajes, setMensajes] = useState<Mensaje[]>([])
  const [respondiendo, setRespondiendo] = useState(false)
  const espera = useRef<ReturnType<typeof setTimeout> | null>(null)
  const proximo = useRef(1)

  const enviar = (texto: string) => {
    setMensajes((lista) => [...lista, { id: proximo.current++, from: "user", texto }])
    setRespondiendo(true)
    espera.current = setTimeout(() => {
      const respuesta = RESPUESTAS[texto] ?? "Eso no lo tengo a mano todavía."
      setMensajes((lista) => [...lista, { id: proximo.current++, from: "assistant", texto: respuesta }])
      setRespondiendo(false)
    }, 1400)
  }
  const cortar = () => {
    if (espera.current) clearTimeout(espera.current)
    setRespondiendo(false)
  }
  const nueva = () => {
    cortar()
    setMensajes([])
  }
  return { mensajes, respondiendo, enviar, cortar, nueva }
}

def discover_export(kind: str, input_dir: str | Path) -> Path:

    directory = Path(input_dir)
    pattern = EXPORT_PATTERNS[kind]
    try:
        entries = directory.iterdir()
        candidates = sorted(
            (
                entry
                for entry in entries
                if pattern.fullmatch(entry.name) and entry.is_file()
            ),
            key=lambda entry: entry.name,
        )
    except FileNotFoundError:
        candidates = []
    except OSError as e:
        raise ExportDiscoveryError(
            f"could not search for {kind} exports in {directory}: {e}"
        ) from e

    if not candidates:
        raise MissingExportError(kind, directory)
    if len(candidates) > 1:
        raise AmbiguousExportError(
            kind,
            directory,
            tuple(candidate.name for candidate in candidates),
        )
    return candidates[0]

