public static List<Entry> total(Container equipment) {
    Map<Key, Double> sums = new LinkedHashMap<>();
    int slots = Math.min(equipment.getContainerSize(), MobEquipmentContainer.SLOT_COUNT);
    for (int i = 0; i < slots; i++) {
        ItemStack stack = equipment.getItem(i);
        if (stack.isEmpty()) {
            continue;
        }
        EquipmentSlot slot = MobEquipmentContainer.slotFor(i);
        Multimap<Attribute, AttributeModifier> modifiers = stack.getAttributeModifiers(slot);
        for (Map.Entry<Attribute, AttributeModifier> entry : modifiers.entries()) {
            AttributeModifier modifier = entry.getValue();
            sums.merge(new Key(entry.getKey(), modifier.getOperation()),
                    modifier.getAmount(), Double::sum);
        }
    }

    List<Entry> entries = new ArrayList<>();
    sums.forEach((key, amount) -> {
        // 正负相抵为 0 的项不显示 —— 原版 tooltip 同样是逐条列原始值，但摘要是"合计"，
        // 列一条 `+0 护甲` 只会让人以为算错了。
        if (amount != 0.0D) {
            entries.add(new Entry(key.attribute(), key.operation(), amount));
        }
    });
    entries.sort(Comparator
            .comparingInt((Entry entry) -> priorityOf(entry.attribute()))
            .thenComparingInt(entry -> entry.operation().ordinal())
            .thenComparing(entry -> entry.attribute().getDescriptionId()));
    return entries;
}

public static void onIncoming(Text message) {
    var c = AeroClient.CONFIG;
    if (c == null || !c.chatTranslate || message == null) {
        return;
    }
    String line = message.getString();
    if (line.startsWith(MARK) || line.length() > 256) {
        return;
    }
    Matcher m = CHAT.matcher(line.replaceAll("§.", "").trim());
    if (!m.matches()) {
        return;
    }
    String sender = m.group(1) != null ? m.group(1) : m.group(2);
    MinecraftClient mc = MinecraftClient.getInstance();
    if (sender == null || sender.equalsIgnoreCase(mc.getSession().getUsername())) {
        return;
    }
    String body = m.group(3).trim();
    if (body.codePoints().noneMatch(Character::isLetter)) {
        return;
    }
    translate(body, code(c.chatTranslateLang), out -> {
        if (out != null && mc.inGameHud != null) {
            mc.inGameHud.getChatHud().addMessage(Text.literal(MARK + out).formatted(Formatting.GRAY, Formatting.ITALIC));
        }
    });
}

public sealed class Pcg32XshRrV1
{
    public const string AlgorithmId = "pcg32-xsh-rr-v1";

    private const ulong Multiplier = 6_364_136_223_846_793_005UL;
    private ulong state;
    private readonly ulong increment;

    private Pcg32XshRrV1(ulong initialState, ulong initialIncrement)
    {
        increment = initialIncrement | 1UL;
        state = 0;
        _ = NextUInt();
        state = unchecked(state + initialState);
        _ = NextUInt();
    }

    public static Pcg32XshRrV1 Create(string worldSeed, string streamName)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(worldSeed);
        ArgumentException.ThrowIfNullOrWhiteSpace(streamName);

        var key = Encoding.UTF8.GetBytes(worldSeed);
        var stateBytes = HMACSHA256.HashData(key, Encoding.UTF8.GetBytes($"{streamName}/state"));
        var incrementBytes = HMACSHA256.HashData(key, Encoding.UTF8.GetBytes($"{streamName}/increment"));
        return new Pcg32XshRrV1(
            BinaryPrimitives.ReadUInt64BigEndian(stateBytes),
            BinaryPrimitives.ReadUInt64BigEndian(incrementBytes));
    }

    public uint NextUInt()
    {
        var oldState = state;
        state = unchecked((oldState * Multiplier) + increment);
        var xorshifted = (uint)(((oldState >> 18) ^ oldState) >> 27);
        var rotation = (int)(oldState >> 59);
        return (xorshifted >> rotation) | (xorshifted << ((-rotation) & 31));
    }
}

